// Gmail Triggerからのデータを正規化し、空のフィールドにデフォルト値を設定
const gmailData = $input.all()[0].json;

// JSON安全化関数：特殊文字をエスケープ
function sanitizeForJson(text) {
  if (!text) return '';

  return text
    .replace(/\\/g, '\\\\')   // バックスラッシュを最初にエスケープ
    .replace(/"/g, '\\"')     // ダブルクォートをエスケープ
    .replace(/\n/g, '\\n')    // 改行をエスケープ
    .replace(/\r/g, '\\r')    // 復帰文字をエスケープ
    .replace(/\t/g, '\\t')    // タブをエスケープ
    .trim();                  // 前後の空白を削除
}

// デフォルト値を設定した正規化されたデータを作成
const normalizedData = {
  // 元のデータをすべて保持
  ...gmailData,

  // 空の場合にデフォルト値を設定 + JSON安全化
  Subject: sanitizeForJson(gmailData.Subject) || '(件名なし)',
  From: sanitizeForJson(gmailData.From) || '(送信者不明)',
  To: sanitizeForJson(gmailData.To) || '(宛先不明)',
  Body: sanitizeForJson(gmailData.Body || gmailData.TextPlain) || '(本文なし)',
  Date: gmailData.Date || new Date().toISOString(),
  MessageId: gmailData.MessageId || gmailData['Message-ID'] || 'unknown'
};

// ログ出力（デバッグ用）
console.log('=== Gmail Data Normalization ===');
console.log('Original From:', gmailData.From);
console.log('Sanitized From:', normalizedData.From);
console.log('Original Subject:', gmailData.Subject);
console.log('Sanitized Subject:', normalizedData.Subject);
console.log('Has Special Characters:', /["\\]/.test(gmailData.From || ''));

return [{ json: normalizedData }];

