// Slackペイロードをパースして構造化
const body = $input.all()[0].json.body;

// payloadが存在しない場合のエラー処理
if (!body.payload) {
  return [{
    json: {
      error: "No payload found",
      originalBody: body
    }
  }];
}

let payload;
try {
  payload = JSON.parse(body.payload);
} catch (error) {
  return [{
    json: {
      error: "Failed to parse payload",
      originalBody: body,
      parseError: error.message
    }
  }];
}

// 必要な情報を抽出・整理
const action = payload.actions && payload.actions[0];
const messageBlocks = payload.message && payload.message.blocks;

// メッセージ内容の抽出
let senderEmail = "";
let subjectInfo = "";
let replyText = "";

if (messageBlocks && messageBlocks.length > 1) {
  // 送信者情報の抽出とクリーンアップ
  if (messageBlocks[1].fields && messageBlocks[1].fields[0]) {
    const rawSender = messageBlocks[1].fields[0].text.split('\n')[1] || "";

    // HTMLエンティティをデコード
    const decodedSender = rawSender
      .replace(/"/g, '')
      .replace(/&lt;/g, '<')
      .replace(/&gt;/g, '>');

    // Slackのmailtoリンク形式を処理: <mailto:email|display>
    const mailtoMatch = decodedSender.match(/<mailto:([^|]+)\|([^>]+)>/);
    if (mailtoMatch) {
      senderEmail = mailtoMatch[1];
    } else {
      // 通常の Name <email@example.com> 形式
      const emailMatch = decodedSender.match(/<([^>]+)>/);
      if (emailMatch) {
        senderEmail = emailMatch[1]; // メールアドレス部分のみ抽出
      } else {
        // メールアドレスのみの場合
        senderEmail = decodedSender.trim();
      }
    }
  }

  // 件名情報の抽出
  if (messageBlocks[1].fields && messageBlocks[1].fields[1]) {
    subjectInfo = messageBlocks[1].fields[1].text.split('\n')[1] || "";
  }

  // 返信テキストの抽出とHTML変換
  if (messageBlocks[2] && messageBlocks[2].text) {
    const fullText = messageBlocks[2].text.text;
    const replyMatch = fullText.match(/reply_text:\s*(.*?)\s*category:/s);
    let rawReplyText = replyMatch ? replyMatch[1].trim() : "";

    // 改行をHTMLタグに変換してJSON安全にする
    replyText = rawReplyText
      .replace(/\r\n/g, '\n')           // Windows改行を統一
      .replace(/\r/g, '\n')             // Mac改行を統一
      .split('\n')                      // 改行で分割
      .map(line => line.trim())         // 各行の前後空白削除
      .filter(line => line.length > 0)  // 空行削除
      .map(line => `<p>${line}</p>`)    // 各行をpタグで囲む
      .join('');                        // 結合
  }
}

// 構造化されたデータを返す
return [{
  json: {
    // アクション情報
    action_id: action ? action.action_id : null,
    button_value: action ? action.value : null,

    // ユーザー・チャンネル情報
    user_id: payload.user ? payload.user.id : null,
    channel_id: payload.channel ? payload.channel.id : null,
    trigger_id: payload.trigger_id || null,
    response_url: payload.response_url || null,

    // メッセージ情報
    sender: senderEmail, // メールアドレスのみ
    subject: subjectInfo,
    reply_text: replyText, // HTML形式に変換済み

    // 原本データ（必要時参照用）
    original_payload: payload,

    // GmailのURL
    gmail_url: action && action.value ? 
      `https://mail.google.com/mail/u/0/#inbox/${action.value}` : 
      null,

    // 処理時刻
    processed_at: new Date().toISOString()
  }
}];

// PDFから抽出されたテキストを取得
const allItems = $input.all();
const text = allItems[0].json.text;
console.log('テキスト総文字数:', text.length);

// テキストが空の場合はエラー
if (!text || !text.trim()) {
  throw new Error('PDFからテキストが抽出されていません');
}

// JSON エスケープ関数
function escapeJsonString(str) {
  return str
    .replace(/\\/g, '\\\\')    // バックスラッシュをエスケープ
    .replace(/"/g, '\\"')      // ダブルクォートをエスケープ
    .replace(/\n/g, ' ')       // 改行を半角スペースに変換
    .replace(/\r/g, ' ')       // キャリッジリターンを半角スペースに変換
    .replace(/\t/g, ' ')       // タブを半角スペースに変換
    .replace(/\f/g, ' ')       // フォームフィードを半角スペースに変換
    .replace(/\b/g, ' ')       // バックスペースを半角スペースに変換
    .replace(/\s+/g, ' ')      // 連続する空白文字を1つのスペースに統合
    .trim();                   // 前後の空白を削除
}

// テキストをチャンクに分割（安全な方法）
const chunkSize = 500;
const chunks = [];

console.log('チャンク処理開始...');

// 単純に500文字ずつ分割
for (let i = 0; i < text.length; i += chunkSize) {
  const chunk = text.slice(i, i + chunkSize).trim();

  if (chunk.length > 0) {
    // JSON エスケープ処理を適用
    const escapedChunk = escapeJsonString(chunk);

    chunks.push({
      pageContent: escapedChunk,
      metadata: {
        chunk_index: chunks.length,
        source: 'pdf_document',
        chunk_size: escapedChunk.length,
        start_position: i
      }
    });

    console.log(`チャンク${chunks.length}作成 (${escapedChunk.length}文字)`);
  }
}

console.log(`生成されたチャンク数: ${chunks.length}`);
console.log('最初のチャンク:', chunks[0]?.pageContent.substring(0, 50) + '...');

const result = chunks.map(chunk => ({ json: chunk }));
console.log('最終出力準備完了');

return result;

// 正しいアプローチ: 前のノードを参照してembeddingとチャンクを合わせる

// 現在のアイテムからembeddingを取得
const embedding = $json.embedding ? $json.embedding.values : null;

// 現在のアイテムインデックスを取得
const currentIndex = $itemIndex;

// 前のノード「テキストをチャンクに分割」から対応するチャンクを取得
const allChunks = $("テキストをチャンクに分割").all();
const chunkText = allChunks[currentIndex].json.pageContent;

console.log(`Processing chunk ${currentIndex}: ${chunkText.substring(0, 50)}...`);
console.log(`Embedding length: ${embedding ? embedding.length : 'none'}`);

// Document形式で出力
return {
    pageContent: chunkText,
    metadata: {
        chunkIndex: currentIndex,
        timestamp: new Date().toISOString(),
        source: 'google_drive_pdf'
    },
    embedding: embedding
};
